insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'consciousness-sleep', 'Consciousness: Problem of definition', 'Philosophers have used the term consciousness for four main topics: knowledge in general, intentionality, introspection (and the knowledge it specifically generates) and phenomenal experience... Something within one''s mind is ''introspectively conscious'' just in case one introspects it (or is poised to do so). Introspection is often thought to deliver one''s primary knowledge of one''s mental life. An experience or other mental entity is ''phenomenally conscious'' just in case there is ''something it is like'' for one to have it. The clearest examples are: perceptual experience, such as tastings and seeings; bodily-sensational experiences, such as those of pains, tickles and itches; imaginative experiences, such as those of one''s own actions or perceptions; and streams of thought, as in the experience of thinking ''in words'' or ''in images''. Introspection and phenomenality seem independent, or dissociable, although this is controversial.', 'Wikipedia: Consciousness', 'https://en.wikipedia.org/w/index.php?title=Consciousness&oldid=1380321482', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'consciousness-sleep' and body = 'Philosophers have used the term consciousness for four main topics: knowledge in general, intentionality, introspection (and the knowledge it specifically generates) and phenomenal experience... Something within one''s mind is ''introspectively conscious'' just in case one introspects it (or is poised to do so). Introspection is often thought to deliver one''s primary knowledge of one''s mental life. An experience or other mental entity is ''phenomenally conscious'' just in case there is ''something it is like'' for one to have it. The clearest examples are: perceptual experience, such as tastings and seeings; bodily-sensational experiences, such as those of pains, tickles and itches; imaginative experiences, such as those of one''s own actions or perceptions; and streams of thought, as in the experience of thinking ''in words'' or ''in images''. Introspection and phenomenality seem independent, or dissociable, although this is controversial.');
